// One-bit cellphone ringer+vibration motor control. The ring input is
// active-high: go to RING state when it goes high for one cycle. The
// vibrate_mode input is active-high: if it's high, always go to VIBRATE
// state, regardless of the ring input.
module TopModule (
    input  ring,
    input  vibrate_mode,
    output reg ringer,
    output reg motor
);
    reg [1:0] state;
    parameter IDLE = 2'b00;
    parameter RING = 2'b01;
    parameter VIBRATE = 2'b10;
    always @(*) begin
        case (state)
            IDLE: begin
                if (ring) state <= RING;
                if (vibrate_mode) state <= VIBRATE;
            end
            RING: begin
                ringer <= 1;
                if (!ring) state <= IDLE;
            end
            VIBRATE: begin
                motor <= 1;
                if (!vibrate_mode) state <= IDLE;
            end
        endcase
    end
    always @(*) begin
        if (state == RING) ringer <= 1; else ringer <= 0;
        if (state == VIBRATE) motor <= 1; else motor <= 0;
    end
endmodule

